const gcAggregatedStats = require("../lib/GcAggregatedStats"); // No I18N
const constants = require("./constants"); // No I18N

describe("Overall GC aggregated stats", () => {
  const gcMetricsAggs = new gcAggregatedStats();
  beforeEach(() => {
    //aggregating stats
    var gcStatsSampleSet = constants.GC_STATS;
    gcStatsSampleSet.forEach((stats) => {
      gcMetricsAggs.aggregateStats(stats);
    });
  }, 1);

  //Testing member method types
  test("defines aggregateStats()", () => {
    expect(typeof gcMetricsAggs.aggregateStats).toBe("function");
  });

  test("defines getAsJsonArray()", () => {
    expect(typeof gcMetricsAggs.getAsJsonArray).toBe("function");
  });

  test("defines reset()", () => {
    expect(typeof gcMetricsAggs.reset).toBe("function");
  });

  //Testing return types of each method
  test("aggregateStats() returns undefined when called", () => {
    expect(gcMetricsAggs.aggregateStats(constants.GC_STATS[0])).toBeUndefined();
  });

  test("getAsJsonArray() returns truthy value when called", () => {
    expect(gcMetricsAggs.getAsJsonArray()).toBeTruthy();
  });

  test("reset() returns truthy undefined when called", () => {
    expect(gcMetricsAggs.reset()).toBeUndefined();
  });

  //Testing functionality of each function
  test("getAsJsonArray() returns correct value when called", () => {
    var result = gcMetricsAggs.getAsJsonArray();

    //checking all keys present in the result.
    result.forEach((element) => {
      expect(element).toHaveProperty("name");
      expect(element).toHaveProperty("sum");
      expect(element).toHaveProperty("max");
      expect(element).toHaveProperty("min");
      expect(element).toHaveProperty("count");
      expect(element).toHaveProperty("avg");
    });

    //final result check
    expect(result).toStrictEqual(constants.GC_STATS_AGGREGATED_VALUE);
  });

  test("resetting the gcStats Map", () => {
    expect(gcMetricsAggs.reset());
  });
});
